import{_ as o,o as e,c as r,a2 as t}from"./chunks/framework.BSdKG9Lk.js";const g=JSON.parse('{"title":"06 — Diagnóstico & Plano","description":"","frontmatter":{},"headers":[],"relativePath":"docs-legados/06-diagnostico.md","filePath":"docs-legados/06-diagnostico.md","lastUpdated":1786474711000}'),n={name:"docs-legados/06-diagnostico.md"};function i(s,a,d,c,l,u){return e(),r("div",null,[...a[0]||(a[0]=[t('<h1 id="_06-—-diagnostico-plano" tabindex="-1">06 — Diagnóstico &amp; Plano <a class="header-anchor" href="#_06-—-diagnostico-plano" aria-label="Permalink to &quot;06 — Diagnóstico &amp; Plano&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Documento original</p><p>Conteúdo integral preservado de <code>docs/06-diagnostico-e-plano-de-engenharia.md</code>. Parte da wiki para manter a rastreabilidade com a documentação histórica do projeto.</p></div><blockquote><p><strong>Status:</strong> Análise Diagnóstica e Roadmap de Refatoração<br><strong>Objetivo:</strong> Elevar o sistema de &quot;Protótipo Avançado (Mockado)&quot; para &quot;Sistema em Produção 100% Funcional e Integrado&quot;.</p></blockquote><hr><h2 id="_1-visao-geral-do-diagnostico" tabindex="-1">1. Visão Geral do Diagnóstico <a class="header-anchor" href="#_1-visao-geral-do-diagnostico" aria-label="Permalink to &quot;1. Visão Geral do Diagnóstico&quot;">​</a></h2><p>O sistema <strong>Ampla Vendas ERP</strong> atualmente possui uma excelente base de UI (React + Tailwind) e uma fundação conceitual forte para resiliência offline usando Dexie.js (IndexedDB). No entanto, uma análise profunda do código atual revela débitos técnicos significativos e <em>gaps</em> arquiteturais que caracterizam o sistema atual como um <strong>protótipo avançado</strong>, não pronto para produção.</p><p>Se colocado em produção no estado atual, o sistema apresentará problemas graves de escalabilidade de código, dessincronização de dados mestre e perda de pedidos em cenários de fechamento abrupto da aplicação.</p><p>Mudanças estruturais serão necessárias.</p><hr><h2 id="_2-erros-fundamentais-e-debitos-tecnicos-identificados" tabindex="-1">2. Erros Fundamentais e Débitos Técnicos Identificados <a class="header-anchor" href="#_2-erros-fundamentais-e-debitos-tecnicos-identificados" aria-label="Permalink to &quot;2. Erros Fundamentais e Débitos Técnicos Identificados&quot;">​</a></h2><h3 id="_2-1-inbound-sync-carga-de-dados-mestre-inexistente" tabindex="-1">2.1. Inbound Sync (Carga de Dados Mestre) Inexistente <a class="header-anchor" href="#_2-1-inbound-sync-carga-de-dados-mestre-inexistente" aria-label="Permalink to &quot;2.1. Inbound Sync (Carga de Dados Mestre) Inexistente&quot;">​</a></h3><ul><li><strong>O Problema (Erro Crasso):</strong> O banco local (<code>src/db/db.ts</code>) está sendo populado com dados falsos (<em>mocks</em> locais via função <code>seedDatabase</code>). Não existe rotina para baixar o catálogo real de Produtos, Clientes e Condições de Pagamento do Supabase para o IndexedDB local.</li><li><strong>Impacto no Negócio:</strong> O vendedor nunca verá novos produtos, alterações de preços ou atualizações nos limites de crédito dos clientes.</li><li><strong>Ação Corretiva:</strong> Substituir o <code>seedDatabase</code> mockado por rotinas reais de <em>Pull/Fetch</em> da API REST do Supabase (<code>pullClients</code>, <code>pullProducts</code>), salvando-os no Dexie.js de forma assíncrona.</li></ul><h3 id="_2-2-o-adapter-via-microservico-e-apenas-teorico" tabindex="-1">2.2. O &quot;Adapter via Microserviço&quot; é apenas Teórico <a class="header-anchor" href="#_2-2-o-adapter-via-microservico-e-apenas-teorico" aria-label="Permalink to &quot;2.2. O &quot;Adapter via Microserviço&quot; é apenas Teórico&quot;">​</a></h3><ul><li><strong>O Problema:</strong> A documentação cita um Middleware/Adapter para integração com ERPs (SAP/TOTVS), mas no código há apenas o envio direto da PWA para o Supabase (<code>syncOrderToSupabase</code>). O Supabase atua apenas como banco, não como integrador.</li><li><strong>Impacto no Negócio:</strong> Pedidos chegam no Supabase, mas nunca chegarão ao ERP do cliente.</li><li><strong>Ação Corretiva:</strong> É necessária a implantação de um backend (ex: Supabase Edge Functions em Deno/TypeScript ou um Server Node.js) que &quot;escute&quot; as inserções no Supabase e converta o Payload Canônico em requisições específicas (SOAP/OData/REST) para o ERP do cliente.</li></ul><h3 id="_2-3-sincronizacao-outbound-assincrona-ingenua" tabindex="-1">2.3. Sincronização Outbound Assíncrona Ingênua <a class="header-anchor" href="#_2-3-sincronizacao-outbound-assincrona-ingenua" aria-label="Permalink to &quot;2.3. Sincronização Outbound Assíncrona Ingênua&quot;">​</a></h3><ul><li><strong>O Problema:</strong> A sincronização para a nuvem depende que a aba do navegador esteja aberta e que o usuário ou um loop simples dispare a função.</li><li><strong>Impacto no Negócio:</strong> Se o usuário cria um pedido no modo avião e, logo depois, fecha o aplicativo, o pedido ficará preso no celular infinitamente até o app ser reaberto, podendo causar perda de faturamento.</li><li><strong>Ação Corretiva:</strong> Implementar Service Workers com a API de <strong>Background Sync</strong> e arquitetura de Fila Outbox real no Dexie.js.</li></ul><h3 id="_2-4-arquitetura-monolitica-de-estado-no-frontend-app-tsx" tabindex="-1">2.4. Arquitetura Monolítica de Estado no Frontend (<code>App.tsx</code>) <a class="header-anchor" href="#_2-4-arquitetura-monolitica-de-estado-no-frontend-app-tsx" aria-label="Permalink to &quot;2.4. Arquitetura Monolítica de Estado no Frontend (`App.tsx`)&quot;">​</a></h3><ul><li><strong>O Problema:</strong> O arquivo principal <code>App.tsx</code> possui cerca de 400 linhas e atua como um &quot;God Object&quot;, controlando quase todos os estados globais (abas ativas, listas de dados, modais abertos).</li><li><strong>Impacto Técnico:</strong> À medida que o sistema crescer, o <em>prop drilling</em> (passar propriedades dezenas de níveis para baixo) tornará a manutenção lenta e dolorosa.</li><li><strong>Ação Corretiva:</strong> Implantar uma biblioteca de gerenciamento de estado global (como <strong>Zustand</strong> ou <strong>React Context API</strong>) para abstrair a lógica de negócio para fora da camada visual.</li></ul><hr><h2 id="_3-plano-de-engenharia-e-implantacao-roadmap-4-sprints" tabindex="-1">3. Plano de Engenharia e Implantação (Roadmap 4 Sprints) <a class="header-anchor" href="#_3-plano-de-engenharia-e-implantacao-roadmap-4-sprints" aria-label="Permalink to &quot;3. Plano de Engenharia e Implantação (Roadmap 4 Sprints)&quot;">​</a></h2><p>Este roadmap define as intervenções diretas na base de código para evoluir o sistema.</p><h3 id="sprint-1-fundacao-e-sincronizacao-reversa-inbound" tabindex="-1">Sprint 1: Fundação e Sincronização Reversa (Inbound) <a class="header-anchor" href="#sprint-1-fundacao-e-sincronizacao-reversa-inbound" aria-label="Permalink to &quot;Sprint 1: Fundação e Sincronização Reversa (Inbound)&quot;">​</a></h3><ol><li><strong>Remoção de Mocks:</strong> Eliminar dados falsos do <code>src/db/db.ts</code>.</li><li><strong>Setup Supabase Completo:</strong> Implantar as tabelas descritas no Script DDL dentro de um projeto real Supabase.</li><li><strong>Inbound Sync Layer:</strong> Criar arquivo <code>src/lib/syncEngine.ts</code> contendo funções para fazer download (<code>SELECT</code>) de <code>produtos</code>, <code>clientes</code> e <code>condicoes_pagamento</code> do Supabase e fazer o Upsert (inserção/atualização) local no Dexie.js.</li><li><strong>Login Real:</strong> Substituir a verificação estática de PIN em <code>UserProfilesManager.tsx</code> pelo <strong>Supabase Auth</strong> (JWT Tokens).</li></ol><h3 id="sprint-2-roteamento-seguranca-e-arquitetura-de-estado-ui-ux" tabindex="-1">Sprint 2: Roteamento, Segurança e Arquitetura de Estado (UI/UX) <a class="header-anchor" href="#sprint-2-roteamento-seguranca-e-arquitetura-de-estado-ui-ux" aria-label="Permalink to &quot;Sprint 2: Roteamento, Segurança e Arquitetura de Estado (UI/UX)&quot;">​</a></h3><ol><li><strong>Roteamento Seguro (<code>react-router-dom</code>):</strong> Substituir a navegação por estado no <code>App.tsx</code> por rotas reais.</li><li><strong>Separação de Contextos &amp; Auth Guards:</strong> Criar rotas abertas para o App (<code>/</code>) e proteger a documentação estratégica (<code>/docs</code>) usando Google OAuth ou Supabase Auth.</li><li><strong>Lazy Loading e Chunking:</strong> Garantir que o código sensível da documentação e painéis administrativos só sejam trafegados para usuários logados e autorizados.</li><li><strong>Desacoplamento de <code>App.tsx</code>:</strong> Criar uma store Zustand (ex: <code>useAppStore.ts</code>) contendo variáveis de controle globais (usuário logado, aba ativa, status de conexão).</li></ol><h3 id="sprint-3-robustez-offline-e-fila-de-sincronizacao-outbox" tabindex="-1">Sprint 3: Robustez Offline e Fila de Sincronização (Outbox) <a class="header-anchor" href="#sprint-3-robustez-offline-e-fila-de-sincronizacao-outbox" aria-label="Permalink to &quot;Sprint 3: Robustez Offline e Fila de Sincronização (Outbox)&quot;">​</a></h3><ol><li><strong>Configuração de PWA Completo:</strong> Configurar <code>vite-plugin-pwa</code> para gerar o arquivo de manifesto real (<code>manifest.json</code>) e instalar o aplicativo.</li><li><strong>Service Worker de Fila:</strong> Criar um script rodando no fundo que detecta o evento <code>window.addEventListener(&#39;online&#39;)</code> e varre a tabela <code>orders</code> do Dexie.js onde <code>statusSync === &#39;pendente_sync&#39;</code>, enviando-os lote a lote.</li></ol><h3 id="sprint-4-middleware-e-integracao-erp-legado-adapters" tabindex="-1">Sprint 4: Middleware e Integração ERP Legado (Adapters) <a class="header-anchor" href="#sprint-4-middleware-e-integracao-erp-legado-adapters" aria-label="Permalink to &quot;Sprint 4: Middleware e Integração ERP Legado (Adapters)&quot;">​</a></h3><ol><li><strong>Edge Functions Supabase:</strong> Codificar uma Edge Function (Deno) para ser o gatilho (<code>Trigger</code>) quando um novo registro entrar na tabela <code>pedidos</code>.</li><li><strong>Roteamento Canônico:</strong> A Edge Function disparará requisições formatadas (XML ou JSON complexo) para os IPs externos dos ERPs (Protheus, SAP, etc).</li><li><strong>Gerenciamento de DLQ (Falhas):</strong> Se o ERP recusar o pedido (ex: Cliente Bloqueado), o Supabase retornará via WebSocket a rejeição para o celular do vendedor, atualizando o pedido para <code>status_sync = &#39;erro&#39;</code>.</li></ol><hr><h2 id="_4-conclusao-da-analise" tabindex="-1">4. Conclusão da Análise <a class="header-anchor" href="#_4-conclusao-da-analise" aria-label="Permalink to &quot;4. Conclusão da Análise&quot;">​</a></h2><p>O estado atual da base de código possui um excelente Design System (Tailwind) e uma prova de conceito de banco de dados offline sólida (Dexie). No entanto, para ser considerado um produto B2B final <strong>100% funcional</strong>, a barreira dos &quot;dados falsos&quot; deve ser rompida.</p><p>Implementar a comunicação bidirecional real com o Supabase e adotar um estado global robusto (Zustand) são as premissas inegociáveis para o próximo estágio do projeto. As mudanças não destruirão o que foi feito em nível visual, mas alterarão drasticamente o núcleo lógico de roteamento de dados.</p>',33)])])}const m=o(n,[["render",i]]);export{g as __pageData,m as default};
